CREATE OR REPLACE EDITIONABLE FUNCTION "%USER_NAME%"."SESSION_END" (P_SID NUMBER) RETURN DATE 
AS
    rDate DATE;
BEGIN
    FOR c IN (
        SELECT
            date_session,
            time_end
        FROM sessions
        WHERE s_id = p_sid
        )
    LOOP
        rDate := c.time_end + (c.date_session - TRUNC(c.time_end, 'DD'));
    END LOOP;

    RETURN rDate;
END SESSION_END;
/
